namespace Notifications;

/// <summary>Runs a message through validation, throttling, rendering and delivery.</summary>
public sealed class DispatchPipeline
{
    private readonly ITemplateStore _templates;
    private readonly UnsubscribeList _unsubscribed;

    public DispatchPipeline(ITemplateStore templates, UnsubscribeList unsubscribed)
    {
        _templates = templates;
        _unsubscribed = unsubscribed;
    }

    public string Run(Message message, int attempt)
    {
        if (TryGetValidationError(message, out var error))
            return error;

        if (attempt > 5)
            return "throttled";

        var template = _templates.Get(message.Subject);
        if (template == null)
            return "no template";

        var body = Render(message, template);
        return GetDispatchResult(body, attempt);
    }

    private bool TryGetValidationError(Message message, out string error)
    {
        if (string.IsNullOrEmpty(message.Body))
        {
            error = "empty body";
            return true;
        }

        var recipient = message.Recipient;
        if (message.Channel == Channel.Email && !recipient.EmailAddress.Contains('@'))
        {
            error = "invalid email";
            return true;
        }

        if (message.Channel == Channel.Sms && recipient.Phone.Length < 5)
        {
            error = "invalid phone";
            return true;
        }

        if (_unsubscribed.IsUnsubscribed(recipient.EmailAddress))
        {
            error = "unsubscribed";
            return true;
        }

        error = string.Empty;
        return false;
    }

    private static string Render(Message message, string template)
    {
        return message.Channel switch
        {
            Channel.Email => template + message.Body,
            Channel.Sms => message.Body,
            Channel.Push => message.Subject,
            _ => message.Body
        };
    }

    private static string GetDispatchResult(string body, int attempt)
    {
        if (attempt > 0 && body.Length > 0)
            return $"retry:{attempt}:{body.Length}";
        if (body.Length == 0)
            return "empty render";
        return $"sent:{body.Length}";
    }
}
